from collections import deque
from typing import List

def process_balls_sequence(n: int, sizes: List[int]) -> int:
    sequence = deque()

    for A_i in sizes:
        current_size = 2 ** A_i
        sequence.append(current_size)

        while len(sequence) > 1 and sequence[-1] == sequence[-2]:
            last = sequence.pop()
            sequence.pop()
            sequence.append(last * 2)

    return len(sequence)
